sys_script_client.script:
function onChange(control, oldValue, newValue, isLoading) {

    if (isLoading || newValue == '')
        return;

    var allFields = [
        'department',
        'user_password',
        'password_needs_reset',
        'locked_out',
        'x_snc_trackmed_d_guardian_name',
        'x_snc_trackmed_d_doctor_name',
        'x_snc_trackmed_d_pateint_name',
        'x_snc_trackmed_d_caregiver_name',
        'x_snc_trackmed_d_rel_care_pat',
        'x_snc_trackmed_d_care_facili_centre',
        'company'
    ];

    // Make all fields visible first
    for (var i = 0; i < allFields.length; i++) {
        g_form.setVisible(allFields[i], true);
    }

    // Hospital Supervisor
    if (newValue == 'hospital_admin') {

        hideFields([
            'department',
            'user_password',
            'password_needs_reset',
            'locked_out',
            'x_snc_trackmed_d_guardian_name',
            'x_snc_trackmed_d_doctor_name',
            'x_snc_trackmed_d_pateint_name',
            'x_snc_trackmed_d_caregiver_name',
            'x_snc_trackmed_d_rel_care_pat',
            'x_snc_trackmed_d_care_facili_centre'
        ]);

    }

    // Care Facility Supervisor
    else if (newValue == 'organization_admin') {

        hideFields([
            'department',
            'user_password',
            'password_needs_reset',
            'locked_out',
            'x_snc_trackmed_d_guardian_name',
            'x_snc_trackmed_d_doctor_name',
            'x_snc_trackmed_d_pateint_name',
            'x_snc_trackmed_d_caregiver_name',
            'x_snc_trackmed_d_rel_care_pat',
            'x_snc_trackmed_d_care_facili_centre'
        ]);

    }

    // Doctor
    else if (newValue == 'doctor') {

        hideFields([
            'department',
            'user_password',
            'password_needs_reset',
            'locked_out',
            'x_snc_trackmed_d_guardian_name',
            'x_snc_trackmed_d_doctor_name',
            'x_snc_trackmed_d_pateint_name',
            'x_snc_trackmed_d_caregiver_name',
            'x_snc_trackmed_d_rel_care_pat',
            'x_snc_trackmed_d_care_facili_centre'
        ]);

    }

    // Pharmacist
    else if (newValue == 'pharmacist') {

        hideFields([
            'department',
            'user_password',
            'password_needs_reset',
            'locked_out',
            'x_snc_trackmed_d_guardian_name',
            'x_snc_trackmed_d_pateint_name',
            'x_snc_trackmed_d_caregiver_name',
            'x_snc_trackmed_d_rel_care_pat',
            'x_snc_trackmed_d_care_facili_centre',
            'x_snc_trackmed_d_doctor_name'
        ]);

    }

    // Caretaker
    else if (newValue == 'care_taker') {

        hideFields([
            'department',
            'user_password',
            'password_needs_reset',
            'locked_out',
            'x_snc_trackmed_d_guardian_name',
            'x_snc_trackmed_d_doctor_name',
            'x_snc_trackmed_d_caregiver_name',
            'x_snc_trackmed_d_rel_care_pat',
            'x_snc_trackmed_d_care_facili_centre'
        ]);

    }

    // Guardian
    else if (newValue == 'guardian') {

        hideFields([
            'department',
            'user_password',
            'password_needs_reset',
            'locked_out',
		   'x_snc_trackmed_d_caregiver_name',

            'x_snc_trackmed_d_guardian_name',
            'x_snc_trackmed_d_doctor_name'
        ]);

    }

    // Helper Function
    function hideFields(fields) {

        for (var j = 0; j < fields.length; j++) {
            g_form.setVisible(fields[j], false);
        }

        // Refresh form layout if supported
        if (typeof g_form.layoutSections === 'function') {
            g_form.layoutSections();
        }
    }

}
